import AppKit
import ApplicationServices
import CoreGraphics
import Foundation

func attr(_ item: AXUIElement, _ name: String) -> CFTypeRef? {
    var result: CFTypeRef?
    return AXUIElementCopyAttributeValue(item, name as CFString, &result) == .success ? result : nil
}
let target = URL(fileURLWithPath: CommandLine.arguments[1]).resolvingSymlinksInPath().path
let mode = CommandLine.arguments.count > 2 ? CommandLine.arguments[2] : "inspect"
let matches = NSWorkspace.shared.runningApplications.filter { $0.executableURL?.resolvingSymlinksInPath().path == target }
guard matches.count == 1, let app = matches.first else { print("target_app_not_unique"); exit(2) }
let root = AXUIElementCreateApplication(app.processIdentifier)
guard let extras = attr(root, "AXExtrasMenuBar") else { print("extras_menu_unavailable"); exit(3) }
let menu = unsafeBitCast(extras, to: AXUIElement.self)
let items = attr(menu, kAXChildrenAttribute) as? [AXUIElement] ?? []
var selected: [(AXUIElement, CGPoint, CGSize)] = []
for item in items {
    let role = attr(item, kAXRoleAttribute) as? String ?? ""
    guard role == "AXMenuBarItem" else { continue }
    var point = CGPoint.zero
    var size = CGSize.zero
    guard let p = attr(item, kAXPositionAttribute), let s = attr(item, kAXSizeAttribute),
        CFGetTypeID(p) == AXValueGetTypeID(), CFGetTypeID(s) == AXValueGetTypeID() else { continue }
    guard AXValueGetValue(unsafeBitCast(p, to: AXValue.self), .cgPoint, &point),
        AXValueGetValue(unsafeBitCast(s, to: AXValue.self), .cgSize, &size),
        size.width > 0, size.height > 0 else { continue }
    selected.append((item, point, size))
}
guard selected.count == 1 else { print("status_item_not_unique count=\(selected.count)"); exit(4) }
let (selectedItem, point, size) = selected[0]
var center = CGPoint(x: point.x + size.width / 2, y: point.y + size.height / 2)
if center.y < 0 && center.y >= -60 && center.x >= 0 && center.x < (NSScreen.screens.first?.frame.width ?? 0) {
    guard CGPreflightPostEventAccess() else { print("reveal_permission_missing"); exit(10) }
    let reveal = CGEvent(mouseEventSource: nil, mouseType: .mouseMoved,
        mouseCursorPosition: CGPoint(x:center.x,y:1), mouseButton:.left)
    reveal?.flags = []
    reveal?.post(tap:.cghidEventTap)
    for _ in 0..<30 {
        usleep(100000)
        var newPoint = CGPoint.zero
        var newSize = CGSize.zero
        if let p = attr(selectedItem,kAXPositionAttribute), let z = attr(selectedItem,kAXSizeAttribute),
            CFGetTypeID(p)==AXValueGetTypeID(), CFGetTypeID(z)==AXValueGetTypeID(),
            AXValueGetValue(unsafeBitCast(p,to:AXValue.self),.cgPoint,&newPoint),
            AXValueGetValue(unsafeBitCast(z,to:AXValue.self),.cgSize,&newSize) {
            center = CGPoint(x:newPoint.x+newSize.width/2,y:newPoint.y+newSize.height/2)
            if center.y >= 0 { break }
        }
    }
}
guard center.x >= 0, center.y >= 0,
      NSScreen.screens.contains(where: { screen in
          let top = (NSScreen.screens.first?.frame.maxY ?? 0) - screen.frame.maxY
          return CGRect(x:screen.frame.minX,y:top,width:screen.frame.width,height:screen.frame.height).contains(center)
      }) else { print("status_item_offscreen x=\(center.x) y=\(center.y) screens=\(NSScreen.screens.map { String(describing: $0.frame) })"); exit(5) }
if mode == "click" {
    guard CGPreflightPostEventAccess(), AXIsProcessTrusted() else { print("event_permission_missing"); exit(6) }
    var hit: AXUIElement?
    guard AXUIElementCopyElementAtPosition(AXUIElementCreateSystemWide(), Float(center.x), Float(center.y), &hit) == .success, let hit else { print("target_hit_unavailable"); exit(8) }
    var hitPID: pid_t = 0
    AXUIElementGetPid(hit, &hitPID)
    guard hitPID == app.processIdentifier else { print("target_hit_mismatch"); exit(9) }
    let source = CGEventSource(stateID: .hidSystemState)
    guard let down = CGEvent(mouseEventSource: source, mouseType: .leftMouseDown, mouseCursorPosition: center, mouseButton: .left),
          let up = CGEvent(mouseEventSource: source, mouseType: .leftMouseUp, mouseCursorPosition: center, mouseButton: .left) else { exit(7) }
    let at = DispatchTime.now().uptimeNanoseconds
    down.setIntegerValueField(.mouseEventClickState, value:1)
    up.setIntegerValueField(.mouseEventClickState, value:1)
    down.flags = []
    up.flags = []
    let move = CGEvent(mouseEventSource: source, mouseType: .mouseMoved, mouseCursorPosition: center, mouseButton: .left)
    move?.flags = []
    move?.post(tap: .cghidEventTap)
    usleep(100000)
    down.post(tap:.cghidEventTap)
    usleep(100000)
    up.post(tap:.cghidEventTap)
    print("{\"posted\":true,\"pid\":\(app.processIdentifier),\"uptime_ns\":\(at),\"x\":\(center.x),\"y\":\(center.y)}")
} else {
    print("{\"located\":true,\"pid\":\(app.processIdentifier),\"x\":\(center.x),\"y\":\(center.y)}")
}
